CREATE OR REPLACE FUNCTION public.invalidate_student_portrait_faces() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.photo_url IS DISTINCT FROM OLD.photo_url THEN DELETE FROM public.student_face_descriptors WHERE student_id = NEW.id; UPDATE public.face_registration_requests SET status='cancelled', descriptors=NULL, photo_urls=ARRAY[]::text[], review_notes='Portrait changed; enrollment invalidated', updated_at=now() WHERE student_id=NEW.id AND status='pending'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.invalidate_student_portrait_faces() FROM PUBLIC;
CREATE TRIGGER invalidate_student_portrait_faces AFTER UPDATE OF photo_url ON public.students FOR EACH ROW EXECUTE FUNCTION public.invalidate_student_portrait_faces();
CREATE OR REPLACE FUNCTION public.sync_profile_portrait_and_invalidate_faces() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE portrait text; BEGIN IF NEW.avatar_url IS DISTINCT FROM OLD.avatar_url OR NEW.avatar_full_url IS DISTINCT FROM OLD.avatar_full_url THEN portrait := COALESCE(NULLIF(NEW.avatar_full_url,''),NULLIF(NEW.avatar_url,'')); DELETE FROM public.student_face_descriptors WHERE student_id IN (SELECT id FROM public.students WHERE auth_user_id=NEW.id OR (NEW.student_code IS NOT NULL AND student_code=NEW.student_code)); UPDATE public.face_registration_requests SET status='cancelled', descriptors=NULL, photo_urls=ARRAY[]::text[], review_notes='Profile portrait changed; enrollment invalidated',updated_at=now() WHERE status='pending' AND student_id IN (SELECT id FROM public.students WHERE auth_user_id=NEW.id OR (NEW.student_code IS NOT NULL AND student_code=NEW.student_code)); UPDATE public.students SET photo_url=portrait WHERE (auth_user_id=NEW.id OR (NEW.student_code IS NOT NULL AND student_code=NEW.student_code)) AND photo_url IS DISTINCT FROM portrait; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.sync_profile_portrait_and_invalidate_faces() FROM PUBLIC;
CREATE TRIGGER sync_profile_portrait_and_invalidate_faces AFTER UPDATE OF avatar_url,avatar_full_url ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.sync_profile_portrait_and_invalidate_faces();